'use client';

import { useState, useEffect, useMemo, useRef } from 'react';
import { useGeolocation } from '@/hooks/useGeolocation';
import { Species, Observation, IconicTaxon, MONTH_NAMES } from '@/lib/types';
import { SpeciesCard } from '@/components/SpeciesCard';
import { SeasonSelector } from '@/components/SeasonSelector';
import { TaxonFilter } from '@/components/TaxonFilter';
import { LocationDisplay } from '@/components/LocationDisplay';
import { SpeciesPanel } from '@/components/SpeciesModal';
import dynamic from 'next/dynamic';

// Dynamic import for map (client-side only, no SSR)
const ObservationMap = dynamic(
  () => import('@/components/ObservationMap').then((mod) => mod.ObservationMap),
  {
    ssr: false,
    loading: () => (
      <div className="w-full h-full bg-white flex items-center justify-center">
        <span className="text-xs text-gray-600 uppercase tracking-wide">Loading map...</span>
      </div>
    ),
  }
);

export default function Home() {
  const { coordinates, loading: locationLoading, error: locationError, isDefault, requestLocation } = useGeolocation();

  const [species, setSpecies] = useState<Species[]>([]);
  const [observations, setObservations] = useState<Observation[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
  const [selectedTaxon, setSelectedTaxon] = useState<IconicTaxon | 'all'>('all');
  const [selectedSpecies, setSelectedSpecies] = useState<Species | null>(null);
  const [focusedSpeciesId, setFocusedSpeciesId] = useState<number | null>(null);
  const [hoveredObservation, setHoveredObservation] = useState<Observation | null>(null);
  const [showFilters, setShowFilters] = useState(true);
  const speciesCardRefs = useRef<Map<number, HTMLButtonElement>>(new Map());

  // Fetch species when location or month changes
  useEffect(() => {
    if (!coordinates) return;

    async function fetchData() {
      setLoading(true);
      setError(null);

      try {
        const lat = coordinates!.lat;
        const lng = coordinates!.lng;
        const [speciesRes, obsRes] = await Promise.all([
          fetch(`/api/species?lat=${lat}&lng=${lng}&month=${selectedMonth}&limit=100`),
          fetch(`/api/observations?lat=${lat}&lng=${lng}&radius=5&limit=200`),
        ]);

        if (!speciesRes.ok) throw new Error('Failed to fetch species');
        if (!obsRes.ok) throw new Error('Failed to fetch observations');

        const speciesData = await speciesRes.json();
        const obsData = await obsRes.json();

        setSpecies(speciesData.species || []);
        setObservations(obsData.observations || []);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Something went wrong');
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, [coordinates, selectedMonth]);

  // Filter species by taxon
  const filteredSpecies = useMemo(() => {
    if (selectedTaxon === 'all') return species;
    return species.filter((s) => s.iconicTaxon === selectedTaxon);
  }, [species, selectedTaxon]);

  // Filter observations by taxon and month
  const filteredObservations = useMemo(() => {
    // Create a map of species IDs to their iconic taxon for quick lookup
    const speciesTaxonMap = new Map<number, string>();
    species.forEach((s) => {
      speciesTaxonMap.set(s.id, s.iconicTaxon);
    });

    return observations.filter((obs) => {
      // Filter by taxon
      if (selectedTaxon !== 'all') {
        const obsTaxon = speciesTaxonMap.get(obs.speciesId);
        if (obsTaxon !== selectedTaxon) {
          return false;
        }
      }

      // Filter by month (extract month from observedOn date string)
      if (obs.observedOn) {
        try {
          const obsDate = new Date(obs.observedOn);
          const obsMonth = obsDate.getMonth() + 1; // getMonth() returns 0-11
          if (obsMonth !== selectedMonth) {
            return false;
          }
        } catch (e) {
          // If date parsing fails, include the observation
        }
      }

      return true;
    });
  }, [observations, species, selectedTaxon, selectedMonth]);

  // Count species by taxon for filters
  const taxonCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    species.forEach((s) => {
      const taxon = s.iconicTaxon || 'unknown';
      counts[taxon] = (counts[taxon] || 0) + 1;
    });
    return counts;
  }, [species]);

  const currentMonth = new Date().getMonth() + 1;
  const isCurrentMonth = selectedMonth === currentMonth;

  // Clear focused species when filters change
  useEffect(() => {
    setFocusedSpeciesId(null);
  }, [selectedTaxon, selectedMonth]);

  // Scroll highlighted species card into view
  useEffect(() => {
    if (hoveredObservation) {
      const speciesId = hoveredObservation.speciesId;
      const cardElement = speciesCardRefs.current.get(speciesId);
      if (cardElement) {
        cardElement.scrollIntoView({
          behavior: 'smooth',
          block: 'nearest',
        });
      }
    }
  }, [hoveredObservation]);

  return (
    <main className="h-screen w-screen overflow-hidden relative">
      {/* Full-screen map */}
      <div className="absolute inset-0 z-10">
        {coordinates ? (
          <ObservationMap
            center={coordinates}
            observations={filteredObservations}
            focusedSpeciesId={focusedSpeciesId}
            onObservationClick={(obs) => {
              const found = species.find((s) => s.id === obs.speciesId);
              if (found) setSelectedSpecies(found);
            }}
            onObservationHover={setHoveredObservation}
            hoveredObservationId={hoveredObservation?.id || null}
          />
        ) : (
          <div className="w-full h-full bg-white flex items-center justify-center">
            <span className="text-xs text-gray-600 uppercase tracking-wide">Loading location...</span>
          </div>
        )}
      </div>

      {/* Toolbar overlay on top of map */}
      <header className="absolute top-0 right-0 z-50 pointer-events-none">
        <div className="max-w-md ml-auto">
          <div className="bg-white border-b border-l border-black px-6 py-4 pointer-events-auto">
            <div>
              <h1 className="text-sm font-medium uppercase tracking-wider text-black">
                Species Neighbor
              </h1>
              <p className="text-xs text-gray-600 mt-0.5 uppercase tracking-wide">
                Discover wildlife around you
              </p>
            </div>
          </div>
        </div>
      </header>

      {/* Toggle button for filters */}
      <button
        onClick={() => setShowFilters(!showFilters)}
        className={`absolute top-4 left-4 z-50 w-10 h-10 border border-black bg-white text-black
                   flex items-center justify-center hover:bg-black hover:text-white transition-colors
                   ${showFilters ? '' : ''}`}
        aria-label="Toggle filters"
      >
        {showFilters ? (
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        )}
      </button>

      {/* Filters overlay panel */}
      {showFilters && (
        <div className="absolute inset-y-0 left-0 w-[400px] bg-white border-r border-black overflow-y-auto z-40 slide-in-from-left">
        <div className="p-8">
          {/* Location */}
          <div className="mb-6">
            <LocationDisplay
              coordinates={coordinates}
              isDefault={isDefault}
              loading={locationLoading}
              error={locationError}
              onRequestLocation={requestLocation}
            />
          </div>

          {/* Season selector */}
          <div className="mb-4">
            <SeasonSelector
              selectedMonth={selectedMonth}
              onMonthChange={setSelectedMonth}
            />
          </div>

          {/* Taxon filter */}
          <div className="mb-6">
            <TaxonFilter
              selected={selectedTaxon}
              onSelect={setSelectedTaxon}
              counts={taxonCounts}
            />
          </div>

          {/* Title */}
          <div className="mb-6">
            <h2 className="text-xs font-medium uppercase tracking-wider text-black mb-1">
              {isCurrentMonth ? (
                <>Today&apos;s Neighbors</>
              ) : (
                <>{MONTH_NAMES[selectedMonth - 1]} Species</>
              )}
            </h2>
            <p className="text-xs text-gray-600 uppercase tracking-wide">
              {loading ? (
                'Loading...'
              ) : (
                `${filteredSpecies.length} species`
              )}
            </p>
          </div>

          {/* Error */}
          {error && (
            <div className="mb-4 p-4 border border-black bg-white text-black text-xs uppercase tracking-wide">
              {error}
            </div>
          )}

          {/* Loading state */}
          {loading && (
            <div className="space-y-2">
              {[1, 2, 3, 4, 5].map((i) => (
                <div key={i} className="bg-white p-4 animate-pulse border border-black">
                  <div className="flex items-center gap-4">
                    <div className="w-8 h-8 bg-gray-200" />
                    <div className="w-16 h-16 bg-gray-200" />
                    <div className="flex-1">
                      <div className="h-4 bg-gray-200 w-3/4 mb-2" />
                      <div className="h-3 bg-gray-200 w-1/2" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Species list */}
          {!loading && (
            <div className="space-y-2">
              {filteredSpecies.map((sp, index) => {
                const isHighlighted = hoveredObservation?.speciesId === sp.id;
                return (
                  <div
                    key={sp.id}
                    ref={(el) => {
                      if (el) {
                        const button = el.querySelector('button');
                        if (button) {
                          speciesCardRefs.current.set(sp.id, button);
                        }
                      }
                    }}
                  >
                    <SpeciesCard
                      species={sp}
                      rank={index + 1}
                      onClick={() => {
                        setFocusedSpeciesId(sp.id);
                        setSelectedSpecies(sp);
                      }}
                      isHighlighted={isHighlighted}
                      isFocused={focusedSpeciesId === sp.id}
                    />
                  </div>
                );
              })}

              {filteredSpecies.length === 0 && !error && (
                <div className="text-center py-12 text-gray-600">
                  <p className="text-xs uppercase tracking-wider mb-2">No species found</p>
                  <p className="text-xs text-gray-500 uppercase tracking-wide">Try selecting a different category</p>
                </div>
              )}
            </div>
          )}

          {/* Footer */}
          <footer className="mt-12 pt-6 border-t border-black text-center">
            <p className="text-xs text-gray-600 uppercase tracking-wide">
              Data from{' '}
              <a
                href="https://www.inaturalist.org"
                target="_blank"
                rel="noopener noreferrer"
                className="text-black hover:underline"
              >
                iNaturalist
              </a>
            </p>
          </footer>
        </div>
        </div>
      )}

      {/* Species detail panel */}
      {selectedSpecies && coordinates && (
        <SpeciesPanel
          species={selectedSpecies}
          coordinates={coordinates}
          onClose={() => {
            setSelectedSpecies(null);
            setFocusedSpeciesId(null);
          }}
        />
      )}
    </main>
  );
}
